const esc = s => String(s ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const norm = s => String(s||'').toLowerCase().normalize('NFKD').replace(/[̀-ͯ]/g,'').replace(/[^a-z0-9]+/g,' ').trim();
const first = s => String(s||'').split('\n')[0];
const short = s => first(s).replace(/\((label|SmPC|US label)\)\.?/gi,'').replace(/^HGH(?: policy)?:\s*/,'').trim();
const codesFrom = s => [...new Set(String(s||'').match(/\b89\d{8,9}\b/g)||[])];
const sorted = l => [...l].sort((a,b)=>a.name.localeCompare(b.name,undefined,{sensitivity:'base'}));
const toast = (m, ic='check') => { const t=$('#toast'); t.innerHTML=E(ic)+esc(m); t.classList.add('show'); clearTimeout(t._h); t._h=setTimeout(()=>t.classList.remove('show'),2300); };
const fmtD = (iso,opt={day:'numeric',month:'short',year:'numeric'}) => { const d=new Date(iso); return isNaN(d)?'':d.toLocaleDateString(undefined,opt); };
const fmtDT = t => { const d=new Date(t); return isNaN(d)?'':d.toLocaleString(undefined,{day:'numeric',month:'short',hour:'2-digit',minute:'2-digit'}); };

function tm(name,q){ const h=hl(name,q); if(!/[a-z]/.test(name)) return h; return h.replace(/(^|[^A-Za-z<])([A-Za-z]*[a-z][A-Za-z]*)/g,(m,pre,w)=>(!/[A-Z]{3,}/.test(w))?m:pre+w.replace(/([A-Z]{3,})/g,'<span class="tm">$1</span>')); }
function hl(text,q){ const safe=esc(text); const w=norm(q).split(' ').filter(Boolean).map(x=>x.replace(/[.*+?^${}()|[\]\\]/g,'\\$&')); return w.length?safe.replace(new RegExp('('+w.join('|')+')','gi'),'<mark>$1</mark>'):safe; }
function rich(s){
  const lines=String(s||'').split('\n').map(l=>l.trim()).filter(Boolean);
  if(!lines.length) return '<p style="color:var(--ink-3)">Not specified</p>';
  let h='',ul=false;
  for(const l of lines){
    const b=/^[•\-*]\s+/.test(l); let t=esc(l.replace(/^[•\-*]\s+/,''));
    t=t.replace(/^(HGH(?: policy| product)?)\s*:\s*/,'<span class="loc">$1</span>');
    t=t.replace(/^([A-Za-z0-9][A-Za-z0-9 ()/.%&,≤≥<>+-]{1,40}):\s/,'<b>$1:</b> ');
    if(b){ if(!ul){h+='<ul>';ul=true;} h+='<li>'+t+'</li>'; } else { if(ul){h+='</ul>';ul=false;} h+='<p>'+t+'</p>'; }
  }
  return h+(ul?'</ul>':'');
}
const C128="212222 222122 222221 121223 121322 131222 122213 122312 132212 221213 221312 231212 112232 122132 122231 113222 123122 123221 223211 221132 221231 213212 223112 312131 311222 321122 321221 312212 322112 322211 212123 212321 232121 111323 131123 131321 112313 132113 132311 211313 231113 231311 112133 112331 132131 113123 113321 133121 313121 211331 231131 213113 213311 213131 311123 311321 331121 312113 312311 332111 314111 221411 431111 111224 111422 121124 121421 141122 141221 112214 112412 122114 122411 142112 142211 241211 221114 413111 241112 134111 111242 121142 121241 114212 124112 124211 411212 421112 421211 212141 214121 412121 111143 111341 131141 114113 114311 411113 411311 113141 114131 311141 411131 211412 211214 211232".split(' ');
function barcode(txt){ const v=[104,...[...txt].map(c=>c.charCodeAt(0)-32)]; const chk=v.reduce((a,x,i)=>a+x*(i||1),0)%103; const pat=[...v,chk].map(x=>C128[x]).join('')+'2331112'; let x=10,r=''; [...pat].forEach((w,i)=>{w=+w; if(i%2===0) r+=`<rect x="${x}" y="0" width="${w}" height="50"/>`; x+=w;}); return `<svg viewBox="0 0 ${x+10} 50" preserveAspectRatio="none" role="img" aria-label="Barcode ${esc(txt)}">${r}</svg>`; }

function score(d,q){
  if(!q) return 1;
  const qn=norm(q), terms=qn.split(' '), name=norm(d.name), al=norm(d.aliases), codes=(d.cernerCodes||[]).join(' ');
  const body=norm([d.product,d.diluents,d.drugClass,d.dilution,d.comments].join(' '));
  let s=0;
  if(name.startsWith(qn)) s+=100; else if((' '+name).includes(' '+qn)) s+=70; else if(name.includes(qn)) s+=50;
  if(al && (' '+al).includes(' '+qn)) s+=60;
  if(/^\d{3,}$/.test(qn) && codes.includes(qn)) s+=90;
  for(const t of terms){ if(name.includes(t)) s+=8; else if(al.includes(t)) s+=6; else if(codes.includes(t)) s+=6; else if(body.includes(t)) s+=2; else return 0; }
  return s;
}
function results(q=S.q, filter=S.filter){
  const l=S.drugs.filter(d=>filter==='All'||(filter==='High alert'?d.highAlert:d.drugClass===filter));
  if(!q.trim()) return sorted(l);
  return l.map(d=>[d,score(d,q)]).filter(x=>x[1]>0).sort((a,b)=>b[1]-a[1]||a[0].name.localeCompare(b[0].name)).map(x=>x[0]);
}

