function grow(t){requestAnimationFrame(()=>{t.style.height='auto';t.style.height=(t.scrollHeight+3)+'px';});}
function renderX(){ $('#xl').innerHTML=(editing.extra||[]).map((x,i)=>`<div class="xrow"><div><div class="f"><input class="xl" placeholder="Section title" value="${esc(x.label)}"></div><div class="f" style="margin:0"><textarea class="xv" rows="2" placeholder="Content">${esc(x.value)}</textarea></div></div><button type="button" class="ib" data-xd="${i}" aria-label="Remove section">${E('wastebasket')}</button></div>`).join(''); $$('#xl textarea').forEach(grow); $$('[data-xd]').forEach(b=>b.onclick=()=>{syncX();editing.extra.splice(+b.dataset.xd,1);renderX();}); $$('#xl .ib .e3').forEach(i=>i.style.cssText='width:24px;height:24px'); }
function syncX(){ editing.extra=$$('#xl .xrow').map(r=>({label:$('.xl',r).value.trim(),value:$('.xv',r).value.trim()})); }
function collect(){
  syncX(); const r={...editing};
  $$('#form [data-k]').forEach(el=>r[el.dataset.k]=el.value.trim());
  r.cernerCodes=String(r.cernerCodes||'').split(/[,\s]+/).filter(Boolean); if(!r.cernerCodes.length) r.cernerCodes=codesFrom(r.product);
  r.references=String(r.refs||'').split('\n').map(l=>l.trim()).filter(Boolean).map(l=>{const [t,...u]=l.split('|');return {title:t.trim(),url:u.join('|').trim()};}); delete r.refs;
  r.highAlert=$('#f_ha').checked; r.extra=r.extra.filter(x=>x.label||x.value); r.drugClass=r.drugClass||'Other';
  return r;
}
