function importList(){
  modal(`<h3>${E('inbox')}Import medicines</h3><p>Paste a JSON list in the export format. Matching IDs are updated and new ones added. Nothing is deleted.</p><textarea id="imT" placeholder='[{"id":"…","name":"…"}]'></textarea><p class="hint" id="imM"></p><div class="acts"><button class="pillbtn" data-close>Cancel</button>${S.drugs.length===0?`<button class="pillbtn" id="imB">Load the 38 starter medicines</button>`:''}<button class="pillbtn grad" id="imG">Import</button></div>`);
  const run=async a=>{ if(!Array.isArray(a)) throw new Error('Expected a JSON list'); let n=0; for(const x of a){ if(!x||!x.name) continue; const r={form:'Injection',drugClass:'Other',highAlert:false,aliases:'',cernerCodes:[],extra:[],references:[],...x}; r.id=r.id||norm(r.name).replace(/ /g,'-').slice(0,60); r.updatedAt=new Date().toISOString(); await S.db.doc('drugs/'+r.id).set(r); upsert(r); n++; $('#imM').textContent=`Imported ${n} of ${a.length}`; } closeModal(); toast(`Imported ${n} medicines`,'inbox'); route(); };
  $('#imG').onclick=async()=>{ try{ await run(JSON.parse($('#imT').value)); }catch(e){ $('#imM').textContent='Import stopped: '+(e.message||'check the JSON and your edit access'); } };
  $('#imB')&&($('#imB').onclick=async()=>{ try{ await run(BUNDLED); }catch(e){ $('#imM').textContent='Import stopped: '+(e.message||''); } });
}


